import { isReactRenderable, useAllowClear as useClearConfig } from '@rc-component/util';
import { useMemo } from 'react';
export const useAllowClear = (prefixCls, displayValues, allowClear, clearIcon, disabled = false, mergedSearchValue, mode) => {
  const allowClearConfig = useClearConfig(allowClear);
  return useMemo(() => {
    const mergedAllowClear = !disabled && !allowClearConfig.disabled && (displayValues.length || mergedSearchValue) && !(mode === 'combobox' && mergedSearchValue === '');
    return {
      ...allowClearConfig,
      allowClear: mergedAllowClear,
      clearIcon: mergedAllowClear ? isReactRenderable(allowClearConfig.clearIcon) ? allowClearConfig.clearIcon : isReactRenderable(clearIcon) ? clearIcon : '×' : null,
      label: mergedAllowClear ? allowClearConfig.label ?? 'Clear' : ''
    };
  }, [allowClearConfig, clearIcon, disabled, displayValues.length, mergedSearchValue, mode]);
};